mapper.select:
SELECT tdm32_company_id
  FROM tdm32_role_digm
 WHERE tdm32_role_digm_id = #{roleDigmId}

SELECT tdm32_role_digm_id AS role_digm_id, tdm32_company_id AS company_id, tdm32_company_nm AS company_name, TO_CHAR(tdm32_reg_date, 'YYYY-MM-DD') AS reg_date, TO_CHAR(tdm32_allc_std_date, 'YYYY-MM-DD') AS allc_std_date, tdm32_reason_nm AS reason_name, tdm32_use_file_type AS use_file_type, tdm32_use_file_type_nm AS use_file_type_name, tdm32_appr_id AS appr_id, tdm32_appr_status_cd AS appr_status_code, tdm32_appr_status_nm AS appr_status_name, tdm32_role_digm_file_id AS role_digm_file_id FROM ( SELECT tdm32_role_digm.* , f_get_company_nm(tdm32_company_id) AS tdm32_company_nm , f_cdnm('TdmDescRegReason', tdm32_reason_cd, tdm32_company_id, tdm32_reg_date) AS tdm32_reason_nm , f_cdnm('TdmUseFileType', tdm32_use_file_type, tdm32_company_id, tdm32_reg_date) AS tdm32_use_file_type_nm , COALESCE(apr01_status_cd, '00') AS tdm32_appr_status_cd , f_cdnm('AprStatusCode', apr01_status_cd, tdm32_company_id, tdm32_reg_date) AS tdm32_appr_status_nm , ( CASE WHEN b.tdm33_role_digm_file_id IS NOT NULL THEN b.tdm33_role_digm_file_id ELSE a.tdm33_role_digm_file_id END ) AS tdm32_role_digm_file_id FROM tdm32_role_digm LEFT OUTER JOIN apr01_appr ON apr01_appr_id = tdm32_appr_id LEFT OUTER JOIN tdm33_role_digm_file a ON a.tdm33_role_digm_id = tdm32_role_digm_id AND a.tdm33_file_type = '1' LEFT OUTER JOIN tdm33_role_digm_file b ON b.tdm33_role_digm_id = tdm32_role_digm_id AND b.tdm33_file_type = '2' LEFT OUTER JOIN sys10_file c ON c.sys10_parent_id = a.tdm33_role_digm_file_id LEFT OUTER JOIN sys10_file d ON d.sys10_parent_id = b.tdm33_role_digm_file_id WHERE 1=1 AND tdm32_use_file_type = '1'
AND tdm32_company_id = #{companyId}
AND tdm32_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)
AND COALESCE(apr01_status_cd, '00') IN ('10','20','30')
) t ORDER BY tdm32_company_nm COLLATE "ko-KR-x-icu", tdm32_reg_date DESC

SELECT  tdm33_role_digm_file_id
  FROM  tdm33_role_digm_file
 WHERE  tdm33_role_digm_id = #{roleDigmId}
   AND  tdm33_file_type LIKE #{fileType}

SELECT tdm32_role_digm_id AS role_digm_id, tdm32_company_id AS company_id, TO_CHAR(tdm32_reg_date, 'YYYY-MM-DD') AS reg_date, TO_CHAR(tdm32_allc_std_date, 'YYYY-MM-DD') AS allc_std_date, tdm32_reason_cd AS reason_code, tdm32_reason_nm AS reason_name, tdm32_use_file_type AS use_file_type, tdm32_appr_id AS appr_id, tdm32_appr_status_cd AS appr_status_code, tdm32_appr_status_nm AS appr_status_name, tdm32_role_digm_file_id AS role_digm_file_id, tdm32_file_type_nm_02 AS file_type_name_02 FROM ( SELECT tdm32_role_digm.* , f_cdnm('TdmDescRegReason', tdm32_reason_cd, tdm32_company_id, tdm32_reg_date) AS tdm32_reason_nm , COALESCE(apr01_status_cd, '00') AS tdm32_appr_status_cd , f_cdnm('AprStatusCode', apr01_status_cd, tdm32_company_id, tdm32_reg_date) AS tdm32_appr_status_nm , ( CASE WHEN b.tdm33_role_digm_file_id IS NOT NULL THEN b.tdm33_role_digm_file_id ELSE a.tdm33_role_digm_file_id END ) AS tdm32_role_digm_file_id , d.sys10_file_nm AS tdm32_file_type_nm_02 FROM tdm32_role_digm LEFT OUTER JOIN apr01_appr ON apr01_appr_id = tdm32_appr_id LEFT OUTER JOIN tdm33_role_digm_file a ON a.tdm33_role_digm_id = tdm32_role_digm_id AND a.tdm33_file_type = '1' LEFT OUTER JOIN tdm33_role_digm_file b ON b.tdm33_role_digm_id = tdm32_role_digm_id AND b.tdm33_file_type = '2' LEFT OUTER JOIN sys10_file c ON c.sys10_parent_id = a.tdm33_role_digm_file_id LEFT OUTER JOIN sys10_file d ON d.sys10_parent_id = b.tdm33_role_digm_file_id WHERE tdm32_company_id = #{companyId}
AND tdm32_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)
AND COALESCE(apr01_status_cd, '00') NOT IN ('30')
) t ORDER BY tdm32_reg_date DESC

mapper.delete:
DELETE FROM tdm33_role_digm_file f WHERE NOT EXISTS (SELECT 1 FROM sys10_file WHERE sys10_parent_id = f.tdm33_role_digm_file_id) AND f.tdm33_role_digm_id IN ( SELECT tdm32_role_digm_id FROM tdm32_role_digm LEFT OUTER JOIN apr01_appr ON apr01_appr_id = tdm32_appr_id WHERE tdm32_company_id = #{companyId}
AND tdm32_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)
AND COALESCE(apr01_status_cd, '00') NOT IN ('30')
)

mapper.update:
UPDATE tdm32_role_digm
   SET tdm32_reg_date      = #{regDate}
     , tdm32_allc_std_date = #{allcStdDate}
     , tdm32_reason_cd     = #{reasonCode}
     , tdm32_upd_nm        = #{updName}
     , tdm32_upd_date      = f_sysdate()
 WHERE tdm32_role_digm_id = #{roleDigmId}
   AND tdm32_company_id   = #{companyId}

mapper.delete:
DELETE FROM tdm32_role_digm
 WHERE tdm32_company_id = #{companyId}
   AND tdm32_role_digm_id IN
#{roleDigmId}

