SELECT  s.sys10_file_id
  FROM  tdm33_role_digm_file f
        INNER JOIN sys10_file s ON s.sys10_parent_id = f.tdm33_role_digm_file_id
 WHERE  f.tdm33_role_digm_id = #{roleDigmId}
   AND  f.tdm33_file_type = #{fileType}

mapper.delete:
DELETE FROM tdm33_role_digm_file
 WHERE tdm33_role_digm_id = #{roleDigmId}
   AND tdm33_file_type = #{fileType}
